//! The decision, sealing and polling around one clipboard change.

use symcockpit_contract::Error;

use super::{
    ClipStore, ClipboardSettings, ItemMeta, Key, KeyStore, Kind, NewItem, PasteboardSource,
    SettingsStore, crypto,
};

/// Marker types password managers and apps put on secrets (nspasteboard.org). A copy that
/// carries any of them is never stored.
pub const SECURE_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

const TEXT_TYPES: [&str; 2] = ["public.utf8-plain-text", "NSStringPboardType"];
const PNG_TYPE: &str = "public.png";

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Payload {
    Text(String),
    Png(Vec<u8>),
}

impl Payload {
    fn kind(&self) -> Kind {
        match self {
            Payload::Text(_) => Kind::Text,
            Payload::Png(_) => Kind::Image,
        }
    }
    fn bytes(&self) -> &[u8] {
        match self {
            Payload::Text(t) => t.as_bytes(),
            Payload::Png(b) => b,
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Clip {
    pub source: Option<String>,
    pub payload: Payload,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SkipReason {
    Disabled,
    Paused,
    SecureType,
    ExcludedApp,
    NoSupportedType,
    Empty,
    Oversized,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Outcome {
    Stored(String),
    Skipped(SkipReason),
}

/// The privacy rules, before any content is read. `types` are the pasteboard type ids.
pub fn decide(
    s: &ClipboardSettings,
    types: &[String],
    source: Option<&str>,
) -> Result<(), SkipReason> {
    if !s.enabled {
        return Err(SkipReason::Disabled);
    }
    if s.paused {
        return Err(SkipReason::Paused);
    }
    if types.iter().any(|t| SECURE_TYPES.contains(&t.as_str())) {
        return Err(SkipReason::SecureType);
    }
    if source.is_some_and(|app| s.excluded_apps.iter().any(|x| x == app)) {
        return Err(SkipReason::ExcludedApp);
    }
    Ok(())
}

/// Plain layout that gets sealed: `source length (u32 LE) || source || data`. The source app
/// is sealed with the content: a bundle id is as telling as a process name (Q08).
fn pack(source: Option<&str>, data: &[u8]) -> Vec<u8> {
    let src = source.unwrap_or("").as_bytes();
    let mut out = Vec::with_capacity(4 + src.len() + data.len());
    out.extend_from_slice(&(src.len() as u32).to_le_bytes());
    out.extend_from_slice(src);
    out.extend_from_slice(data);
    out
}

fn unpack(plain: &[u8]) -> Option<(Option<String>, &[u8])> {
    let len = u32::from_le_bytes(plain.get(..4)?.try_into().ok()?) as usize;
    let src = std::str::from_utf8(plain.get(4..4 + len)?).ok()?;
    Some(((!src.is_empty()).then(|| src.to_owned()), &plain[4 + len..]))
}

fn aad(id: &str, kind: Kind) -> Vec<u8> {
    format!("{id}|{}", kind.name()).into_bytes()
}

/// Stores clips. Owns no state; every call re-reads the settings.
pub struct Capture<'a> {
    pub settings: &'a dyn SettingsStore,
    pub keys: &'a dyn KeyStore,
    pub store: &'a dyn ClipStore,
}

impl Capture<'_> {
    /// Seals and stores `clip` after the privacy rules (given the pasteboard `types`).
    pub fn store_clip(&self, clip: &Clip, types: &[String], now: i64) -> Result<Outcome, Error> {
        let s = self.settings.load()?;
        if let Err(reason) = decide(&s, types, clip.source.as_deref()) {
            return Ok(Outcome::Skipped(reason));
        }
        let data = clip.payload.bytes();
        if data.is_empty() {
            return Ok(Outcome::Skipped(SkipReason::Empty));
        }
        if data.len() > s.max_item_bytes {
            return Ok(Outcome::Skipped(SkipReason::Oversized));
        }
        let kind = clip.payload.kind();
        let id = crate::finder::new_job_id();
        let key = self.keys.key()?;
        let sealed = crypto::seal(&key, &aad(&id, kind), &pack(clip.source.as_deref(), data));
        self.store.insert(&NewItem {
            meta: ItemMeta {
                id: id.clone(),
                created_at: now,
                kind,
                size: data.len() as u64,
            },
            sealed,
        })?;
        self.store.prune(now, s.max_items, s.max_age_secs)?;
        Ok(Outcome::Stored(id))
    }
}

/// Opens one item for the human (the app). `None` when it is gone or cannot be authenticated.
pub fn open_item(
    keys: &dyn KeyStore,
    store: &dyn ClipStore,
    meta: &ItemMeta,
) -> Result<Option<Clip>, Error> {
    let Some(blob) = store.read_sealed(&meta.id)? else {
        return Ok(None);
    };
    let key: Key = keys.key()?;
    let Some(plain) = crypto::open(&key, &aad(&meta.id, meta.kind), &blob) else {
        return Ok(None);
    };
    let Some((source, data)) = unpack(&plain) else {
        return Ok(None);
    };
    let payload = match meta.kind {
        Kind::Text => Payload::Text(String::from_utf8_lossy(data).into_owned()),
        Kind::Image => Payload::Png(data.to_vec()),
    };
    Ok(Some(Clip { source, payload }))
}

/// Watches `changeCount`. The first call only takes the baseline: what was on the clipboard
/// before capturing started is never read.
#[derive(Default)]
pub struct Poller {
    last: Option<i64>,
}

impl Poller {
    /// `None`: nothing changed. Otherwise what happened to the new content.
    pub fn poll(
        &mut self,
        src: &dyn PasteboardSource,
        capture: &Capture,
        now: i64,
    ) -> Option<Result<Outcome, Error>> {
        let count = src.change_count();
        let previous = self.last.replace(count)?;
        if previous == count {
            return None;
        }
        Some(self.capture_change(src, capture, now))
    }

    fn capture_change(
        &self,
        src: &dyn PasteboardSource,
        capture: &Capture,
        now: i64,
    ) -> Result<Outcome, Error> {
        let settings = capture.settings.load()?;
        let types = src.types();
        let source = src.source_bundle_id();
        // Decide before reading any content.
        if let Err(reason) = decide(&settings, &types, source.as_deref()) {
            return Ok(Outcome::Skipped(reason));
        }
        let payload = if types.iter().any(|t| TEXT_TYPES.contains(&t.as_str())) {
            src.read_text().map(Payload::Text)
        } else if types.iter().any(|t| t == PNG_TYPE) {
            src.read_png().map(Payload::Png)
        } else {
            return Ok(Outcome::Skipped(SkipReason::NoSupportedType));
        };
        match payload {
            Some(payload) => capture.store_clip(&Clip { source, payload }, &types, now),
            None => Ok(Outcome::Skipped(SkipReason::Empty)),
        }
    }
}
